function generiqueHebreu(mot) {
    const direct = GENERIQUES_HEBREUX.get(mot);
    if (direct !== undefined)
        return direct;
    if (mot.length < 4)
        return undefined;
    if (mot.startsWith("ו")) {
        const g = GENERIQUES_HEBREUX.get(mot.slice(1));
        if (g !== undefined)
            return g === "" ? "and" : `and ${g}`;
    }
    if (mot.startsWith("ה")) {
        const g = GENERIQUES_HEBREUX.get(mot.slice(1));
        if (g !== undefined)
            return g;
    }
    return undefined;
}
